def solve():
    solutions = []
    for b in range(1, 100):
        D = (2**(b+1) - 1)**2 - 8 * 3**b
        if D < 0:
            continue
        c = int(D**0.5)
        if c*c == D:
            X = 2**(b+1) - 1
            a1 = (X + c) // 2
            a2 = (X - c) // 2
            if a1 > 0:
                solutions.append((a1, b))
            if a2 > 0 and a1 != a2:
                solutions.append((a2, b))
    return solutions

print(solve())

